export function parseRange(spec) {
    const m = /^(\d+)-(\d+)$/.exec(String(spec).trim());
    if (!m) return null;
    const start = Number(m[1]);
    const end = Number(m[2]);
    return start >= 1 && end >= start ? { start, end } : null;
}

export function summarizeRun(records) {
    const requests = records.length;
    const billableTokens = records.reduce((sum, r) => sum + (r.tokens || 0), 0);
    const maxContext = records.reduce((max, r) => Math.max(max, r.context || 0), 0);
    return { requests, billableTokens, maxContext };
}
